import { type AtlasRole } from "@/lib/auth";
import { requireAtlasUser, type LegacyAtlasRole } from "@/lib/server/requireAtlasUser";

export const runtime = "nodejs";

const PDF_ALLOWED_ROLES: readonly AtlasRole[] = [
  "super_admin",
  "admin",
  "manager",
  "dispatcher",
  "tecnico",
];
const PDF_ALLOWED_LEGACY_ROLES: readonly LegacyAtlasRole[] = ["owner"];

type DbRecord = Record<string, unknown>;

const PAGE_WIDTH = 595;
const PAGE_HEIGHT = 842;
const LEFT = 28;
const RIGHT = 567;
const CONTENT_WIDTH = RIGHT - LEFT;

const SECOM_LOGO = {
  width: 360,
  height: 449,
  data: "",
};

const KIWA_LOGO = {
  width: 120,
  height: 221,
  data: "",
};

function text(record: DbRecord | null | undefined, keys: string[], fallback = "") {
  if (!record) return fallback;
  for (const key of keys) {
    const value = record[key];
    if (value !== null && value !== undefined && String(value).trim() !== "") return String(value).trim();
  }
  return fallback;
}

function num(record: DbRecord | null | undefined, keys: string[], fallback = 0) {
  const value = Number(text(record, keys, ""));
  return Number.isFinite(value) ? value : fallback;
}

function clean(input: unknown) {
  return String(input ?? "")
    .replace(/&nbsp;/gi, " ")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/\r/g, "")
    .replace(/[ \t]+/g, " ")
    .replace(/\n[ \t]+/g, "\n")
    .trim();
}

function pdfText(input: unknown) {
  return clean(input)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2013\u2014]/g, "-")
    .replace(/[^\x09\x0A\x0D\x20-\x7E]/g, "")
    .replace(/\\/g, "\\\\")
    .replace(/\(/g, "\\(")
    .replace(/\)/g, "\\)");
}

function normalize(input: unknown) {
  return clean(input)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function dateOnly(value: string) {
  if (!value) return "-";
  return String(value).slice(0, 10);
}

function durationLabel(minutes: number) {
  if (!minutes || !Number.isFinite(minutes) || minutes <= 0) return "-";
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  if (h && m) return `${h}h ${m}m`;
  if (h) return `${h}h`;
  return `${m}m`;
}

function renderTemplate(template: string, ticket: DbRecord, workOrder: DbRecord | null) {
  const source: Record<string, string> = {
    ticket_id: text(ticket, ["id"], ""),
    glpi_ticket_id: text(ticket, ["glpi_ticket_id", "glpiTicketId"], ""),
    titolo: text(ticket, ["title", "name", "subject"], ""),
    descrizione: text(ticket, ["problem", "description", "content", "glpi_description"], ""),
    cliente: text(ticket, ["customer_name", "customerName", "customer", "entity"], ""),
    sede: text(ticket, ["site_name", "siteName", "site", "location"], ""),
    citta: text(ticket, ["city"], ""),
    regione: text(ticket, ["region"], ""),
    tecnico: text(workOrder, ["technician_name"], text(ticket, ["technician", "assigned_to", "glpi_technician_group"], "")),
    durata: durationLabel(num(workOrder, ["duration_minutes"], num(ticket, ["intervention_duration_minutes", "duration_minutes"], 0))),
    data_apertura: dateOnly(text(ticket, ["opened_at", "created_at", "date"], "")),
    data_chiusura: dateOnly(text(ticket, ["closed_at"], "")),
  };

  return String(template || "").replace(/{{\s*([a-zA-Z0-9_]+)\s*}}/g, (_match, key: string) => source[key] || "");
}

function wrap(input: unknown, maxChars: number) {
  const raw = clean(input);
  const paragraphs = raw.split("\n").map((p) => p.trim()).filter(Boolean);
  const out: string[] = [];
  for (const paragraph of paragraphs.length ? paragraphs : [""]) {
    const words = paragraph.split(/\s+/).filter(Boolean);
    let line = "";
    for (const word of words) {
      const candidate = line ? `${line} ${word}` : word;
      if (candidate.length > maxChars && line) {
        out.push(line);
        line = word;
      } else {
        line = candidate;
      }
    }
    if (line) out.push(line);
  }
  return out.length ? out : [""];
}

function line(x1: number, y1: number, x2: number, y2: number) {
  return `${x1} ${y1} m ${x2} ${y2} l S
`;
}

function rect(x: number, y: number, w: number, h: number) {
  return `${x} ${y} ${w} ${h} re S
`;
}

function fill(x: number, y: number, w: number, h: number, gray = 0.9) {
  return `q ${gray} g ${x} ${y} ${w} ${h} re f Q
`;
}

function textAt(x: number, y: number, value: unknown, size = 10, bold = false) {
  return `BT /${bold ? "F2" : "F1"} ${size} Tf ${x} ${y} Td (${pdfText(value)}) Tj ET
`;
}

function centerText(x: number, y: number, w: number, value: unknown, size = 10, bold = false) {
  const approximate = clean(value).length * size * 0.5;
  const tx = Math.max(x + 2, x + (w - approximate) / 2);
  return textAt(Number(tx.toFixed(1)), y, value, size, bold);
}

function image(name: string, x: number, y: number, w: number, h: number) {
  return `q ${w} 0 0 ${h} ${x} ${y} cm /${name} Do Q
`;
}

function currency(value: number) {
  return `${value.toFixed(2).replace(".", ",")} EUR`;
}

function reportStatus(ticket: DbRecord, workOrder: DbRecord | null) {
  const woStatus = normalize(text(workOrder, ["status"], ""));
  const ticketStatus = normalize(text(ticket, ["status", "ticket_status", "glpi_status"], ""));
  if (text(ticket, ["closed_at"], "") || woStatus.includes("closed") || woStatus.includes("chius") || ticketStatus.includes("chius") || ticketStatus.includes("risol")) return "closed";
  return "open";
}

type PdfPageContent = string;

type PdfSectionInput = {
  title: string;
  lines?: string[];
  table?: Array<Array<string>>;
  minHeight?: number;
};

type ReportData = {
  ticketId: string;
  glpiTicketId: string;
  reportNumber: string;
  customerName: string;
  siteName: string;
  address: string;
  city: string;
  region: string;
  technician: string;
  createdAt: string;
  closedAt: string;
  duration: string;
  plantCode: string;
  objectText: string;
  ticketDescription: string;
  activityText: string;
  modelName: string;
  showMaterials: boolean;
  statusLabel: string;
  statusNote: string;
  materials: DbRecord[];
};

class PdfDoc {
  pages: PdfPageContent[] = [];
  current = "";
  y = 0;
  pageIndex = 0;

  constructor(private data: ReportData) {
    this.newPage(true);
  }

  newPage(first = false) {
    if (this.current) this.pages.push(this.current);
    this.current = "";
    this.pageIndex += 1;
    this.y = 810;

    if (first) {
      this.current += line(LEFT, this.y, RIGHT, this.y);
      this.current += image("ImSecom", 36, 680, 104, 130);
      this.current += image("ImKiwa", 505, 690, 52, 96);
      this.current += textAt(160, 778, "SECOM S.r.l.", 22, true);
      this.current += textAt(160, 756, "Via Monte Cervino, 5", 11);
      this.current += textAt(160, 738, "00071 Pomezia (Roma)", 11);
      this.current += textAt(160, 720, "Tel. +39 06 9146000", 11);
      this.current += textAt(160, 702, "email: assistenza@secomitalia.com", 10);
      this.y = 660;
    } else {
      this.current += textAt(LEFT, 810, "SECOM S.r.l. - Rapporto intervento", 9, true);
      this.current += textAt(420, 810, `Pagina ${this.pageIndex}`, 9);
      this.current += line(LEFT, 798, RIGHT, 798);
      this.y = 770;
    }
  }

  finish() {
    if (this.current) this.pages.push(this.current);
    return this.pages;
  }

  ensure(height: number) {
    if (this.y - height < 55) this.newPage(false);
  }

  box(title: string, height: number) {
    this.ensure(height + 28);
    this.current += fill(LEFT, this.y, CONTENT_WIDTH, 18, 0.82);
    this.current += textAt(LEFT + 8, this.y + 5, title.toUpperCase(), 11, true);
    this.current += rect(LEFT, this.y - height, CONTENT_WIDTH, height + 18);
    this.y -= 26;
  }

  keyValueGrid(title: string, rows: Array<Array<[string, string]>>) {
    const rowHeight = 18;
    const height = rows.length * rowHeight + 12;
    this.box(title, height);

    for (const row of rows) {
      const colWidth = CONTENT_WIDTH / row.length;
      row.forEach(([label, value], index) => {
        const x = LEFT + 8 + index * colWidth;
        const labelW = Math.min(88, colWidth * 0.36);
        this.current += fill(x, this.y - 2, labelW, 16, 0.92);
        this.current += textAt(x + 4, this.y + 3, label, 8, true);
        const valueLines = wrap(value || "-", Math.max(16, Math.floor((colWidth - labelW - 12) / 4.8))).slice(0, 2);
        this.current += textAt(x + labelW + 6, this.y + 3, valueLines[0] || "-", 9);
        if (valueLines[1]) this.current += textAt(x + labelW + 6, this.y - 8, valueLines[1], 7);
      });
      this.y -= rowHeight;
    }
    this.y -= 16;
  }

  reportBanner() {
    this.ensure(48);
    this.current += rect(LEFT, this.y - 40, CONTENT_WIDTH, 40);
    this.current += textAt(LEFT + 12, this.y - 15, "RAPPORTO INTERVENTO", 10, true);
    this.current += textAt(LEFT + 12, this.y - 33, `N. ${this.data.reportNumber}`, 22, true);
    this.current += rect(RIGHT - 155, this.y - 30, 140, 20);
    this.current += centerText(RIGHT - 155, this.y - 24, 140, this.data.statusLabel, 10, true);
    this.y -= 58;
  }

  paragraphSection(title: string, textValue: string, maxChars = 96) {
    const allLines = wrap(textValue || "-", maxChars);
    let index = 0;
    while (index < allLines.length) {
      const linesFit = Math.max(1, Math.floor((this.y - 88) / 12));
      const chunk = allLines.slice(index, index + Math.min(linesFit, 24));
      const height = chunk.length * 12 + 16;
      this.box(title, height);
      for (const row of chunk) {
        this.current += textAt(LEFT + 10, this.y, row, 9);
        this.y -= 12;
      }
      this.y -= 14;
      index += chunk.length;
      if (index < allLines.length) this.newPage(false);
    }
  }

  activitiesSection() {
    const bodyLines = wrap(this.data.activityText || "Attivita tecnica eseguita come da indicazioni operative del ticket.", 92);
    const lines = [...bodyLines];
    let index = 0;

    while (index < lines.length) {
      const linesFit = Math.max(1, Math.floor((this.y - 92) / 13));
      const chunk = lines.slice(index, index + Math.min(linesFit, 22));
      const height = chunk.length * 13 + 18;
      this.box("ATTIVITA'", height);
      for (const row of chunk) {
        this.current += textAt(LEFT + 10, this.y, row, 9);
        this.y -= 13;
      }
      this.y -= 14;
      index += chunk.length;
      if (index < lines.length) this.newPage(false);
    }
  }

  materialsSection() {
    if (!this.data.showMaterials) return;

    const rows = this.data.materials.length
      ? this.data.materials.map((material, index) => [
          text(material, ["name", "material_name", "description"], `Materiale ${index + 1}`),
          String(num(material, ["quantity", "qty"], 1)),
          text(material, ["notes", "note", "description_notes"], ""),
        ])
      : [["", "", ""]];

    const rowHeight = 18;
    const chunkSize = Math.max(1, Math.floor((this.y - 110) / rowHeight));
    let index = 0;

    while (index < rows.length) {
      const chunk = rows.slice(index, index + Math.min(chunkSize, 18));
      const height = 26 + chunk.length * rowHeight + 12;
      this.box("MATERIALE FORNITO / SOSTITUITO", height);
      const x1 = LEFT + 10;
      const x2 = LEFT + 345;
      const x3 = LEFT + 420;
      this.current += fill(x1, this.y - 2, CONTENT_WIDTH - 20, 16, 0.93);
      this.current += textAt(x1 + 4, this.y + 3, "Descrizione materiale", 8, true);
      this.current += textAt(x2 + 4, this.y + 3, "Q.ta", 8, true);
      this.current += textAt(x3 + 4, this.y + 3, "Note", 8, true);
      this.y -= 18;

      for (const [name, qty, notes] of chunk) {
        this.current += line(x1, this.y + 12, RIGHT - 10, this.y + 12);
        this.current += textAt(x1 + 4, this.y, name || " ", 8);
        this.current += textAt(x2 + 4, this.y, qty || " ", 8);
        this.current += textAt(x3 + 4, this.y, notes || " ", 8);
        this.y -= rowHeight;
      }
      this.y -= 14;
      index += chunk.length;
      if (index < rows.length) this.newPage(false);
    }
  }

  outcomeAndSignatures() {
    this.ensure(148);
    this.box("ESITO INTERVENTO", 62);
    this.current += rect(LEFT + 10, this.y - 8, 125, 22);
    this.current += centerText(LEFT + 10, this.y - 2, 125, this.data.statusLabel, 10, true);
    this.current += textAt(LEFT + 150, this.y + 2, this.data.statusNote, 8);
    this.y -= 76;

    this.ensure(78);
    this.current += rect(LEFT + 25, this.y - 58, 205, 58);
    this.current += centerText(LEFT + 25, this.y - 22, 205, "IL CLIENTE", 11, true);
    this.current += centerText(LEFT + 25, this.y - 38, 205, "Timbro e firma", 9);
    this.current += rect(RIGHT - 230, this.y - 58, 205, 58);
    this.current += centerText(RIGHT - 230, this.y - 22, 205, "IL TECNICO", 11, true);
    this.current += centerText(RIGHT - 230, this.y - 38, 205, "Firma", 9);
    this.current += centerText(LEFT, 24, CONTENT_WIDTH, "Documento generato da ATLAS - modello operativo aggiornabile", 7);
    this.y -= 78;
  }
}

function shouldShowMaterials(serviceType: string, template: DbRecord | null, materials: DbRecord[]) {
  if (materials.length > 0) return true;
  const explicit = text(template, ["show_materials", "material_required", "require_materials"], "");
  if (["true", "1", "yes", "si"].includes(explicit.toLowerCase())) return true;
  const key = normalize(`${serviceType} ${text(template, ["template_key", "name"], "")}`);
  return key.includes("material") || key.includes("sostituz");
}

function getTemplateActivityText(template: DbRecord | null, serviceType: string) {
  const activityTemplate = text(template, ["activity_template"], "");
  if (activityTemplate) return activityTemplate;

  if (serviceType === "straordinaria") {
    return "Verifica richiesta utente e controllo preliminare apparato/postazione.\nIntervento eseguito secondo indicazioni operative del ticket.\nEventuali note finali e attivita aggiuntive compilabili dal tecnico prima della chiusura.";
  }

  if (serviceType === "ordinaria") {
    return "Manutenzione ordinaria programmata eseguita secondo piano contrattuale.\nVerifica apparati, collegamenti, alimentazioni e funzionalita generale della postazione.\nEventuali anomalie riscontrate vengono riportate nelle note operative del ticket.";
  }

  if (serviceType === "sepa") {
    return "Verifica aula SEPA e controllo funzionale delle postazioni previste.\nControllo collegamenti, apparati e condizioni operative.\nEventuali anomalie vengono riportate per successiva gestione.";
  }

  if (serviceType.includes("material")) {
    return "Verifica anomalia segnalata.\nSostituzione materiale necessario al ripristino della funzionalita.\nTest finale di corretto funzionamento.";
  }

  return text(template, ["body_template"], "Intervento tecnico eseguito come da richiesta e indicazioni operative del ticket.");
}

function buildReportData(ticket: DbRecord, workOrder: DbRecord | null, activities: DbRecord[], materials: DbRecord[], reportTemplate: DbRecord | null): ReportData {
  const ticketId = text(ticket, ["id"], "-");
  const glpiTicketId = text(ticket, ["glpi_ticket_id", "glpiTicketId"], "-");
  const serviceType = inferServiceType(ticket, workOrder);
  const customerName = text(ticket, ["customer_name", "customerName", "customer", "entity"], "Cliente non definito");
  const siteName = text(ticket, ["site_name", "siteName", "site", "location"], customerName);
  const region = text(ticket, ["region"], "n/d");
  const city = text(ticket, ["city"], "n/d");
  const technician = text(workOrder, ["technician_name"], text(ticket, ["technician", "assigned_to", "glpi_technician_group"], "Non assegnato"));
  const createdAt = dateOnly(text(ticket, ["opened_at", "created_at", "date"], ""));
  const closedAt = dateOnly(text(ticket, ["closed_at"], ""));
  const reportNumber = text(workOrder, ["report_number"], glpiTicketId !== "-" ? glpiTicketId : ticketId);
  const templateObject = renderTemplate(text(reportTemplate, ["default_intervention_object", "intervention_object_template"], ""), ticket, workOrder);
  const objectText = text(workOrder, ["intervention_object", "object"], "") || templateObject || text(ticket, ["title", "name", "subject"], "Intervento ATLAS");
  const durationMinutes = num(workOrder, ["duration_minutes", "intervention_duration_minutes"], num(ticket, ["intervention_duration_minutes", "duration_minutes"], 0));
  const plantCode = text(workOrder, ["plant_code", "system_code"], text(ticket, ["plant_code", "system_code", "code"], "-"));
  const isClosed = reportStatus(ticket, workOrder) === "closed";
  const statusLabel = isClosed ? "CHIUSO" : "NON CHIUSO";
  const statusNote = isClosed
    ? "Intervento completato e pronto per archiviazione."
    : "La durata intervento diventa obbligatoria prima della chiusura e viene riportata qui e nel registro ticket.";

  const ticketDescription = text(ticket, ["problem", "description", "content", "glpi_description"], "-");
  const manualActivity = text(workOrder, ["report_body", "activity_body", "body", "work_description"], "");
  const templateActivity = renderTemplate(getTemplateActivityText(reportTemplate, serviceType), ticket, workOrder);
  const activityText = manualActivity || templateActivity || ticketDescription;

  return {
    ticketId,
    glpiTicketId,
    reportNumber,
    customerName,
    siteName,
    address: text(ticket, ["address", "site_address", "customer_address"], "-"),
    city,
    region,
    technician,
    createdAt,
    closedAt,
    duration: durationMinutes > 0 ? durationLabel(durationMinutes) : isClosed ? "Obbligatoria" : "Da compilare",
    plantCode,
    objectText,
    ticketDescription,
    activityText,
    modelName: text(reportTemplate, ["name"], fallbackModelName(serviceType)),
    showMaterials: shouldShowMaterials(serviceType, reportTemplate, materials),
    statusLabel,
    statusNote,
    materials,
  };
}

function fallbackModelName(serviceType: string) {
  if (serviceType === "ordinaria") return "Ordinaria";
  if (serviceType === "straordinaria") return "Straordinaria - assistenza tecnica";
  if (serviceType === "sepa") return "Aula SEPA";
  if (serviceType.includes("material")) return "Sostituzione materiale";
  return "Modello personalizzato";
}

function buildContentPages(ticket: DbRecord, workOrder: DbRecord | null, activities: DbRecord[], materials: DbRecord[], reportTemplate: DbRecord | null) {
  const data = buildReportData(ticket, workOrder, activities, materials, reportTemplate);
  const doc = new PdfDoc(data);

  doc.keyValueGrid("CLIENTE E SEDE", [
    [["Cliente", data.customerName], ["Sede/Reparto", data.siteName]],
    [["Indirizzo", data.address !== "-" ? data.address : `(${data.city} - ${data.region})`], ["Codice impianto", data.plantCode]],
  ]);
  doc.reportBanner();
  doc.keyValueGrid("DATI OPERATIVI", [
    [["Tecnico", data.technician], ["Apertura", data.createdAt], ["Chiusura", data.closedAt || "-"], ["Durata", data.duration]],
    [["Oggetto", data.objectText]],
  ]);
  doc.paragraphSection("DESCRIZIONE INTERVENTO", data.ticketDescription, 98);
  doc.activitiesSection();
  doc.materialsSection();
  doc.outcomeAndSignatures();

  return doc.finish();
}

function obj(body: string | Buffer) {
  return Buffer.isBuffer(body) ? body : Buffer.from(body, "binary");
}

function imageObject(imageData: { data: string; width: number; height: number }) {
  const data = Buffer.from(imageData.data, "base64");
  return Buffer.concat([
    Buffer.from(`<< /Type /XObject /Subtype /Image /Width ${imageData.width} /Height ${imageData.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${data.length} >>
stream
`, "binary"),
    data,
    Buffer.from("\nendstream", "binary"),
  ]);
}

function buildPdf(ticket: DbRecord, workOrder: DbRecord | null, activities: DbRecord[], materials: DbRecord[], reportTemplate: DbRecord | null) {
  const pages = buildContentPages(ticket, workOrder, activities, materials, reportTemplate);
  const pageContentBuffers = pages.map((page) => Buffer.from(page, "binary"));
  const objects: Buffer[] = [];

  const firstPageObj = 8;
  const kids = pages.map((_page, index) => `${firstPageObj + index * 2} 0 R`).join(" ");

  objects.push(obj("<< /Type /Catalog /Pages 2 0 R >>"));
  objects.push(obj(`<< /Type /Pages /Kids [${kids}] /Count ${pages.length} >>`));
  objects.push(obj("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"));
  objects.push(obj("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>"));
  objects.push(obj("<< /Producer (ATLAS) /Creator (ATLAS Work Orders) >>"));
  objects.push(imageObject(SECOM_LOGO));
  objects.push(imageObject(KIWA_LOGO));

  pageContentBuffers.forEach((contentBuffer, index) => {
    const pageObjNumber = firstPageObj + index * 2;
    const contentObjNumber = pageObjNumber + 1;
    objects.push(obj(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_WIDTH} ${PAGE_HEIGHT}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> /XObject << /ImSecom 6 0 R /ImKiwa 7 0 R >> >> /Contents ${contentObjNumber} 0 R >>`));
    objects.push(Buffer.concat([Buffer.from(`<< /Length ${contentBuffer.length} >>\nstream\n`, "binary"), contentBuffer, Buffer.from("endstream", "binary")]));
  });

  const chunks: Buffer[] = [Buffer.from("%PDF-1.4\n%âãÏÓ\n", "binary")];
  const offsets = [0];

  objects.forEach((body, index) => {
    offsets.push(Buffer.concat(chunks).length);
    chunks.push(Buffer.from(`${index + 1} 0 obj\n`, "binary"), body, Buffer.from("\nendobj\n", "binary"));
  });

  const beforeXref = Buffer.concat(chunks);
  const xrefOffset = beforeXref.length;
  let xref = `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  offsets.slice(1).forEach((offset) => {
    xref += `${String(offset).padStart(10, "0")} 00000 n \n`;
  });
  xref += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R /Info 5 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;
  return Buffer.concat([beforeXref, Buffer.from(xref, "binary")]);
}

async function getOptionalRows(
  supabase: SupabaseClient,
  table: string,
  column: string,
  value: string | number,
  tenantId: string,
) {
  const { data, error } = await supabase
    .from(table)
    .select("*")
    .eq(column, value)
    .eq("tenant_id", tenantId);
  if (error) return [];
  return (data || []) as DbRecord[];
}

function inferServiceType(ticket: DbRecord, workOrder: DbRecord | null) {
  const raw = normalize([
    text(workOrder, ["template_key"], ""),
    text(ticket, ["category", "ticket_type", "service_type", "type", "title"], ""),
  ].join(" "));

  if (raw.includes("stra")) return "straordinaria";
  if (raw.includes("sepa")) return "sepa";
  if (raw.includes("ordin")) return "ordinaria";
  return "custom";
}

async function getReportTemplate(supabase: SupabaseClient, ticket: DbRecord, workOrder: DbRecord | null) {
  const tenantId = text(ticket, ["tenant_id", "tenantId"], "");
  if (!tenantId) return null;

  const templateKey = text(workOrder, ["template_key"], "");
  const serviceType = inferServiceType(ticket, workOrder);

  try {
    let query = supabase
      .from("work_order_report_templates")
      .select("*")
      .eq("tenant_id", tenantId)
      .eq("active", true)
      .order("is_default", { ascending: false })
      .order("updated_at", { ascending: false })
      .limit(1);

    if (templateKey) {
      query = query.or(`template_key.eq.${templateKey},service_type.eq.${serviceType}`);
    } else {
      query = query.eq("service_type", serviceType);
    }

    const { data, error } = await query.maybeSingle();
    if (error) return null;
    return (data || null) as DbRecord | null;
  } catch {
    return null;
  }
}

function fallbackReportTemplate(serviceType: string): DbRecord {
  if (serviceType === "straordinaria") {
    return {
      template_key: "fallback_straordinaria",
      service_type: "straordinaria",
      default_intervention_object: "Intervento straordinario - {{sede}}",
      body_template:
        "Intervento straordinario richiesto per {{sede}}. Eseguite verifiche tecniche, analisi della problematica segnalata e attivita necessarie al ripristino/gestione dell'anomalia. Durata intervento: {{durata}}.",
    };
  }

  if (serviceType === "sepa") {
    return {
      template_key: "fallback_sepa",
      service_type: "sepa",
      default_intervention_object: "Manutenzione aula SEPA - {{sede}}",
      body_template:
        "Manutenzione aula SEPA eseguita presso {{sede}}. Verificati apparati, collegamenti, postazioni e funzionamento generale secondo piano operativo annuale. Durata intervento: {{durata}}.",
    };
  }

  if (serviceType === "ordinaria") {
    return {
      template_key: "fallback_ordinaria",
      service_type: "ordinaria",
      default_intervention_object: "Manutenzione ordinaria - {{sede}}",
      body_template:
        "Manutenzione ordinaria programmata eseguita presso {{sede}}. Effettuate verifiche funzionali, controllo apparati, collegamenti, alimentazioni e stato generale della postazione secondo piano contrattuale. Durata intervento: {{durata}}.",
    };
  }

  return {
    template_key: "fallback_custom",
    service_type: "custom",
    default_intervention_object: "Intervento tecnico - {{sede}}",
    body_template:
      "Intervento tecnico eseguito presso {{sede}}. Attivita svolte come da richiesta e indicazioni operative del ticket. Durata intervento: {{durata}}.",
  };
}

export async function GET(request: NextRequest, context: { params: Promise<{ ticketId: string }> | { ticketId: string } }) {
  try {
    const params = await Promise.resolve(context.params);
    const ticketId = Number(params.ticketId);

    if (!Number.isFinite(ticketId)) {
      return NextResponse.json({ ok: false, error: "ticketId non valido" }, { status: 400 });
    }

    const tenantId = request.nextUrl.searchParams.get("tenantId");
    const auth = await requireAtlasUser(request, {
      tenantId,
      allowedRoles: PDF_ALLOWED_ROLES,
      allowedLegacyRoles: PDF_ALLOWED_LEGACY_ROLES,
    });

    if (!auth.ok) {
      return auth.response;
    }

    const supabase = auth.serviceClient;

    const { data: ticket, error: ticketError } = await supabase
      .from("tickets")
      .select("*")
      .eq("tenant_id", auth.requester.tenantId)
      .eq("id", ticketId)
      .single();

    if (ticketError || !ticket) {
      return NextResponse.json({ ok: false, error: "Ticket non trovato" }, { status: 404 });
    }

    const { data: workOrder } = await supabase
      .from("work_orders")
      .select("*")
      .eq("tenant_id", auth.requester.tenantId)
      .eq("ticket_id", ticketId)
      .maybeSingle();

    const activities = workOrder?.id
      ? await getOptionalRows(supabase, "work_order_activities", "work_order_id", String(workOrder.id), auth.requester.tenantId)
      : [];
    const materials = workOrder?.id
      ? await getOptionalRows(supabase, "work_order_materials", "work_order_id", String(workOrder.id), auth.requester.tenantId)
      : [];
    const serviceType = inferServiceType(ticket as DbRecord, (workOrder || null) as DbRecord | null);
    const template = (await getReportTemplate(supabase, ticket as DbRecord, (workOrder || null) as DbRecord | null)) || fallbackReportTemplate(serviceType);

    const pdf = buildPdf(ticket as DbRecord, (workOrder || null) as DbRecord | null, activities, materials, template);

    return new NextResponse(pdf, {
      status: 200,
      headers: {
        "Content-Type": "application/pdf",
        "Content-Disposition": `inline; filename="bolla-ticket-${ticketId}.pdf"`,
        "Cache-Control": "no-store",
      },
    });
  } catch (error) {
    console.error("[work-order-pdf-by-ticket]", error);
    return NextResponse.json({ ok: false, error: "Errore generazione PDF bolla" }, { status: 500 });
  }
}
